mapper.select:
select a.*,c.`NAME` as deptName, d.`NAME` as dutyName from (select '总部' as userType, ID,`NAME` as name,DEPT_ID,DUTY_ID,`STATUS` as status, SEX,ID_NUMBER,BIRTH,PHONE,HIRE_DATE,POSITIVE_TIME, USER_ID as userId,LEAVE_DATE as leaveDate from PERSONNEL where DELETE_FLAG = 'NOT_DELETE' union all select '分公司' as userType, ID,`NAME` as name,DEPT_ID,DUTY_ID,HR_STATUS as status, SEX,ID_NUMBER,BIRTH,PHONE,HIRE_DATE,POSITIVE_TIME, null as userId,RESIGNATION_TIME as leaveDate from HR_SUB_PERSONNEL where DELETE_FLAG = 'NOT_DELETE'and `STATUS` in ('0', '1')) a LEFT JOIN SYS_ORG c ON a.DEPT_ID = c.ID LEFT JOIN SYS_POSITION d ON a.DUTY_ID = d.ID where 1 = 1
and a.name like CONCAT('%', #{name}, '%')
and a.status = #{status}
and a.userType = #{userType}
